import { CompositeLayer } from "@deck.gl/core";
import { defaultDecoderPool } from "@developmentseed/geotiff";
import { findNearestFrameIndex, normalizeFrameCatalog, parseTimeValue, resolveFrameForTime, } from "./util/frame-catalog.js";
import { FramePrefetcher } from "./frame-prefetcher.js";
import { applyExplicitBucketBucketing, applyMaxFrameRateBucking, scheduleFrameWindow, snapBucketIntervalMs, } from "./util/frame-scheduler.js";
import { SequenceTileCache } from "./sequence-tile-cache.js";
import { TimeSequenceTileLayer } from "./time-sequence-tile-layer.js";
import { GeoTIFFRegistry } from "./util/geotiff-registry.js";
import { detectInteractionMode } from "./util/interaction-mode.js";
import { computePrefetchBackpressureState } from "./util/frame-coverage.js";
import { buildBufferState, buildStats } from "./util/stats-collector.js";
import { buildTileDiagSnapshot } from "./util/tile-diagnostics.js";
import { isEqual } from "lodash-es";
const DEFAULT_MISSING_FRAME_POLICY = "hold-last";
const DEFAULT_SCRUB_BUCKETING_POLICY = {
    enabled: false,
    targetResponseHz: 12,
    minBucketMs: 0,
    maxBucketMs: 15 * 60 * 1000,
    smoothingAlpha: 0.2,
    hysteresisRatio: 0.2,
    snap: "on",
};
/**
 * A deck.gl `CompositeLayer` that orchestrates time-indexed playback of
 * Cloud-Optimized GeoTIFF (COG) sequences.
 *
 * ## Architecture
 *
 * `TimeCOGLayer` owns four long-lived infrastructure objects that it
 * injects into a single persistent `TimeSequenceTileLayer` sublayer:
 *
 * 1. **`SequenceTileCache`** — GPU texture cache keyed by
 *    `(frameId, x, y, z)`.  Serves instant cache hits when the
 *    display frame changes, avoiding the white flash that would occur
 *    if every frame switch destroyed and re-created the tile layer.
 *
 * 2. **`GeoTIFFRegistry`** — Shared GeoTIFF instance cache that
 *    both the sublayer and prefetcher use to open COG files,
 *    eliminating redundant header fetches.
 *
 * 3. **`FramePrefetcher`** — Background pipeline that scores and
 *    fetches tiles for nearby frames before they are needed.
 *
 * 4. **`visibleTileRef`** — Shared mutable state that the inner
 *    `TileLayer` updates whenever the visible tile set changes;
 *    used to feed the prefetcher with the correct tile coordinates.
 *
 * ## Why not one COGLayer per frame?
 *
 * Creating a new `COGLayer` for each displayed frame (the naive
 * approach) destroys all GPU textures, decoded tiles, and in-flight
 * requests on every frame switch.  The resulting cold-start fetch path
 * produces the jarring flicker that this layer exists to eliminate.
 *
 * Instead, `TimeCOGLayer` creates one `TimeSequenceTileLayer` (which
 * extends `COGLayer`) with a **constant** `id`.  deck.gl therefore
 * never destroys it.  Frame changes are communicated by updating
 * `currentFrameId` and `currentFrameUrl` on the sublayer, which in
 * turn propagates them to the inner `TileLayer`'s `updateTriggers.all`.
 * The `updateTriggers` mechanism causes `tileset.reloadAll()` which
 * keeps old tile content visible **until** new data is ready — giving
 * a flicker-free transition.
 */
export class TimeCOGLayer extends CompositeLayer {
    static layerName = "TimeCOGLayer";
    /**
     * Creates the four shared infrastructure objects — `tileCache`,
     * `geotiffRegistry`, `prefetcher`, and `visibleTileRef` — that
     * live for the full lifetime of the layer and are injected into
     * the persistent sublayer on every render.
     */
    initializeState() {
        const props = this.props;
        const tileCache = new SequenceTileCache(props.cachePolicy);
        this.setState({
            catalog: [],
            tileCache,
            geotiffRegistry: new GeoTIFFRegistry(),
            prefetcher: new FramePrefetcher(tileCache, props.schedulerPolicy?.maxNetworkRequests ?? 4, props.schedulerPolicy?.maxDecodeTasks, props.schedulerPolicy?.maxGpuUploadsPerFrame, props.schedulerPolicy?.scoringWeights),
            visibleTileRef: { tiles: [] },
            initialGeotiffUrl: "",
            currentTimeMs: 0,
            targetFrame: null,
            displayFrame: null,
            scheduledFrames: [],
            missing: false,
            lastDisplayedFrameId: null,
            interactionMode: "idle",
            lastInteractionMs: 0,
            lastScrubSample: null,
            scrubRateEWMA: 0,
            lastScrubBucketMs: 0,
            upgradeTimer: null,
            readyFrameIds: new Set(),
        });
    }
    updateState(params) {
        const { props, oldProps } = params;
        const data = props.data?.length === 0 && props.frames !== undefined && props.frames.length > 0 ? props.frames : props.data;
        const oldData = oldProps.data?.length === 0 && oldProps.frames !== undefined && oldProps.frames.length > 0 ? oldProps.frames : oldProps.data;
        const state = this.state;
        const { updateTriggersChanged } = params.changeFlags;
        const parsedCurrentTimeMs = parseTimeValue(props.currentTime);
        const framesChanged = data !== oldData ||
            !!(updateTriggersChanged && (updateTriggersChanged.getTime || updateTriggersChanged.getUrl));
        const cachePolicyChanged = !isEqual(props.cachePolicy, oldProps.cachePolicy);
        const timeChanged = props.currentTime !== oldProps.currentTime;
        const playing = props.playing ?? false;
        const missingFramesWatermarkChanged = props.missingFramesWatermark !== oldProps.missingFramesWatermark;
        const timingChanged = timeChanged ||
            props.playing !== oldProps.playing ||
            props.playbackRate !== oldProps.playbackRate ||
            props.skipMissingFrames !== oldProps.skipMissingFrames ||
            missingFramesWatermarkChanged ||
            !isEqual(props.bufferPolicy, oldProps.bufferPolicy) ||
            !isEqual(props.missingFramePolicy, oldProps.missingFramePolicy);
        if (cachePolicyChanged) {
            state.tileCache.updatePolicy(props.cachePolicy ?? {});
        }
        const catalog = framesChanged
            ? normalizeFrameCatalog(data, props.getTime, props.getUrl)
            : state.catalog;
        if (framesChanged) {
            state.prefetcher.clearMissingFrames();
            this.resetScrubTelemetry();
            this.setState({ catalog });
        }
        if (framesChanged || missingFramesWatermarkChanged) {
            state.prefetcher.pruneMissingFrames(catalog, this.getMissingFramesWatermarkMs());
        }
        if (framesChanged || timingChanged) {
            if (timeChanged) {
                state.lastInteractionMs = Date.now();
                if (playing) {
                    this.resetScrubTelemetry();
                }
                else {
                    this.updateScrubTelemetry(parsedCurrentTimeMs);
                }
            }
            else if (playing && !oldProps.playing) {
                this.resetScrubTelemetry();
            }
            this.updateFrameState(catalog);
        }
    }
    /**
     * Returns the single persistent `TimeSequenceTileLayer` sublayer.
     *
     * The sublayer's `id` is **constant** (`${this.props.id}-tiles`)
     * so that deck.gl reuses the same layer instance across frame
     * switches rather than destroying / recreating it.  Frame changes
     * propagate through `getTileData` in `updateTriggers`, keyed on
     * the current display frame's `id`, which triggers
     * `tileset.reloadAll()` without discarding already-loaded tiles.
     *
     * The `geotiff` prop is set to the very first frame's URL and
     * never changes.  This ensures `COGLayer` computes the shared
     * tileset descriptor exactly once.
     *
     * Frame changes are handled by the shared cache plus a reload of the
     * persistent sublayer's tile data callback for the new frame.
     */
    renderLayers() {
        const state = this.state;
        const frame = state.displayFrame;
        if (!frame) {
            return null;
        }
        // Get passThrough props by excluding this layer's props
        const { id, frames, getTime, getUrl, currentTime, playing, playbackRate, maxFrameRate, descriptorMode, descriptorManifest, missingFramePolicy, bufferPolicy, cachePolicy, qualityPolicy, schedulerPolicy, onFrameReady, onFrameDisplayed, onMissingFrame, onDescriptorMismatch, onBufferStateChange, onStats, getTileData, renderTile, loadOptions, updateTriggers, onViewportLoad, onGeoTIFFLoad, ...passThrough } = this.props;
        const initialUrl = state.initialGeotiffUrl || frame.url;
        return new TimeSequenceTileLayer({
            ...passThrough,
            id: `${id}-tiles`,
            geotiff: initialUrl,
            getTileData: this._getTileDataCallback(frame),
            renderTile,
            loadOptions: frame.requestInit ? {
                ...loadOptions,
                fetch: {
                    ...loadOptions?.fetch,
                    ...frame.requestInit,
                }
            } : loadOptions,
            updateTriggers: {
                renderSubLayers: updateTriggers?.renderTile,
                ...updateTriggers,
                getTileData: frame.id,
            },
            onGeoTIFFLoad: this._getOnGeoTiffLoadCallback(frame),
            onViewportLoad: (loadedTiles) => {
                if (state.visibleTileRef) {
                    state.visibleTileRef.tiles = loadedTiles.map(({ index: { x, y, z } }) => ({ x, y, z }));
                }
                this.updatePrefetch();
                onViewportLoad?.(loadedTiles);
            },
        });
    }
    _getTileDataCallback(frame) {
        const tileCache = this.state.tileCache;
        const registry = this.state.geotiffRegistry;
        if (!tileCache) {
            return undefined;
        }
        const getTileData = this.props.getTileData;
        if (!getTileData) {
            return undefined;
        }
        return async (tile, options) => {
            const { id, url, requestInit } = frame;
            const { x, y, z } = tile.index;
            const hit = tileCache.get(id, x, y, z);
            if (hit) {
                tileCache.recordDisplayHit();
                tileCache.markDisplayed(id, x, y, z);
                return hit;
            }
            tileCache.recordDisplayMiss();
            const result = await registry.loadTile({
                frameId: id,
                url,
                requestInit,
                x,
                y,
                z,
                getTileData,
                options: {
                    device: options.device,
                    signal: options.signal,
                    pool: this.props.pool,
                },
            });
            if (result.status === "ok") {
                tileCache.put(id, x, y, z, {
                    x, y, z,
                    ...result.result,
                    quality: "full",
                    origin: "display",
                });
                return result.result;
            }
            if (result.status === "missing-frame") {
                this.state.prefetcher.markMissingFrame(id, frame.timeMs, this.getMissingFramesWatermarkMs());
                console.warn("TimeCOGLayer: missing frame", { url, x, y, z, err: result.error });
                if (this.props.skipMissingFrames) {
                    this.updateFrameState(this.state.catalog);
                    return null;
                }
                throw result.error;
            }
            if (result.status === "error") {
                console.warn("TimeCOGLayer: tile fetch failed", result.error);
            }
            return null;
        };
    }
    _getOnGeoTiffLoadCallback(frame) {
        const userCallback = this.props.onGeoTIFFLoad;
        if (!this.props.descriptorMode || this.props.descriptorMode === "reuse-first") {
            return userCallback;
        }
        if (this.props.descriptorMode === "manifest" && this.props.descriptorManifest) {
            const manifest = this.props.descriptorManifest;
            return (geotiff, options) => {
                if (geotiff) {
                    const mismatches = [];
                    if (geotiff.overviews.length + 1 !== manifest.overviewCount) {
                        mismatches.push(`overviewCount: expected ${manifest.overviewCount}, got ${geotiff.overviews.length + 1}`);
                    }
                    if (mismatches.length > 0) {
                        this.props.onDescriptorMismatch?.(frame, mismatches.join("; "));
                    }
                }
                userCallback?.(geotiff, options);
            };
        }
        return userCallback;
    }
    /**
     * Aborts all in-flight prefetch tasks, clears the full-res upgrade
     * timer, and destroys GPU textures.
     */
    finalizeState() {
        const state = this.state;
        if (state.upgradeTimer) {
            clearTimeout(state.upgradeTimer);
            state.upgradeTimer = null;
        }
        state.prefetcher?.abortAll();
        state.tileCache?.destroy();
    }
    /**
     * Resolves the target and display frames from the current playback
     * time, computes the scheduled frame window, updates cache
     * protection, fires callbacks, and primes the prefetcher.
     *
     * This is the main orchestration point — called on every prop
     * change that affects timing (`currentTime`, `playing`,
     * `playbackRate`, `bufferPolicy`, `missingFramePolicy`) or the
     * frame catalog itself.
     */
    updateFrameState(catalog) {
        const state = this.state;
        const currentTimeMs = parseTimeValue(this.props.currentTime);
        const playing = this.props.playing ?? false;
        const interactionMode = detectInteractionMode(playing, state.lastInteractionMs, this.props.qualityPolicy?.fullResUpgradeIdleMs);
        const effectiveCatalog = this.props.skipMissingFrames && state.prefetcher.missingFrames.size > 0
            ? catalog.filter((frame) => !state.prefetcher.missingFrames.has(frame.id))
            : catalog;
        const scrubDirectionHint = this.getScrubDirectionHint(currentTimeMs);
        const scrubBucketMs = this.getEffectiveScrubBucketMs(effectiveCatalog, interactionMode);
        const resolution = resolveFrameForTime(effectiveCatalog, currentTimeMs, this.props.missingFramePolicy ?? DEFAULT_MISSING_FRAME_POLICY);
        if (playing && resolution.displayFrame) {
            resolution.displayFrame = applyMaxFrameRateBucking(resolution.displayFrame, effectiveCatalog, state.lastDisplayedFrameId, this.props.maxFrameRate ?? 0, this.props.playbackRate ?? 0, this.props.schedulerPolicy?.frameRateSnap);
        }
        else if (scrubBucketMs > 0 && resolution.displayFrame) {
            resolution.displayFrame = applyExplicitBucketBucketing(resolution.displayFrame, effectiveCatalog, state.lastDisplayedFrameId, scrubBucketMs, scrubDirectionHint < 0 ? "last" : "first");
        }
        const prefetchAnchorFrame = ((playing && (this.props.maxFrameRate ?? 0) > 0) ||
            (!playing && scrubBucketMs > 0)) && resolution.displayFrame
            ? resolution.displayFrame
            : resolution.targetFrame;
        const targetIndex = prefetchAnchorFrame
            ? findNearestFrameIndex(effectiveCatalog, prefetchAnchorFrame.timeMs)
            : -1;
        const scheduledFrames = scheduleFrameWindow(effectiveCatalog, targetIndex, this.props.bufferPolicy, this.props.playbackRate, this.props.maxFrameRate, playing, this.props.schedulerPolicy?.multiscaleLevelPenalty, this.props.schedulerPolicy?.frameRateSnap, scrubBucketMs).map((sf) => sf.frame);
        if (!state.initialGeotiffUrl && resolution.displayFrame) {
            this.setState({
                initialGeotiffUrl: resolution.displayFrame.url,
            });
        }
        if (state.upgradeTimer) {
            clearTimeout(state.upgradeTimer);
            state.upgradeTimer = null;
        }
        if (interactionMode === "seeking" || interactionMode === "scrubbing") {
            const policy = this.props.qualityPolicy ?? {};
            const idleMs = policy.fullResUpgradeIdleMs ?? 150;
            state.upgradeTimer = setTimeout(() => {
                const s = this.state;
                if (s.interactionMode === "seeking" || s.interactionMode === "scrubbing") {
                    s.interactionMode = "idle";
                    this.resetScrubTelemetry();
                    this.updatePrefetch();
                }
            }, idleMs);
        }
        this.setState({
            catalog,
            currentTimeMs,
            targetFrame: resolution.targetFrame,
            displayFrame: resolution.displayFrame,
            scheduledFrames,
            missing: resolution.missing,
            interactionMode,
        });
        if (resolution.displayFrame) {
            const protectedFrames = [
                resolution.displayFrame.id,
                ...scheduledFrames.slice(0, 3).map((f) => f.id),
            ];
            if (state.lastDisplayedFrameId &&
                state.lastDisplayedFrameId !== resolution.displayFrame.id) {
                protectedFrames.push(state.lastDisplayedFrameId);
            }
            state.tileCache.protect(protectedFrames);
        }
        if (resolution.displayFrame &&
            state.lastDisplayedFrameId !== resolution.displayFrame.id) {
            this.props.onFrameDisplayed?.(resolution.displayFrame);
            this.setState({
                lastDisplayedFrameId: resolution.displayFrame.id,
            });
        }
        if (resolution.missing) {
            this.props.onMissingFrame?.(currentTimeMs);
        }
        if (resolution.displayFrame &&
            !state.readyFrameIds.has(resolution.displayFrame.id)) {
            this.checkFrameReady(resolution.displayFrame);
        }
        this.updatePrefetch({
            targetFrame: prefetchAnchorFrame,
            displayFrame: resolution.displayFrame,
            scheduledFrames,
        });
        this.emitState({
            ...state,
            catalog,
            currentTimeMs,
            targetFrame: resolution.targetFrame,
            displayFrame: resolution.displayFrame,
            scheduledFrames,
            missing: resolution.missing,
            interactionMode,
        });
    }
    emitState(s) {
        this.props.onBufferStateChange?.(buildBufferState(s.tileCache, s));
        this.props.onStats?.(buildStats(s.tileCache, s.prefetcher, s), this);
    }
    getMissingFramesWatermarkMs() {
        const watermark = this.props.missingFramesWatermark;
        return watermark === undefined ? null : parseTimeValue(watermark);
    }
    resetScrubTelemetry() {
        const state = this.state;
        state.lastScrubSample = null;
        state.scrubRateEWMA = 0;
        state.lastScrubBucketMs = 0;
    }
    updateScrubTelemetry(currentTimeMs) {
        const state = this.state;
        const now = Date.now();
        const previous = state.lastScrubSample;
        state.lastScrubSample = { wallMs: now, timeMs: currentTimeMs };
        if (!previous) {
            return;
        }
        const deltaWallMs = now - previous.wallMs;
        if (deltaWallMs <= 0) {
            return;
        }
        const sampleRate = Math.abs(currentTimeMs - previous.timeMs) / deltaWallMs;
        if (!Number.isFinite(sampleRate)) {
            return;
        }
        const alpha = this.getScrubBucketingPolicy().smoothingAlpha;
        state.scrubRateEWMA =
            state.scrubRateEWMA > 0
                ? alpha * sampleRate + (1 - alpha) * state.scrubRateEWMA
                : sampleRate;
    }
    getScrubDirectionHint(currentTimeMs) {
        return Math.sign(currentTimeMs - this.state.currentTimeMs) || 1;
    }
    getScrubBucketingPolicy() {
        return {
            ...DEFAULT_SCRUB_BUCKETING_POLICY,
            ...(this.props.scrubBucketingPolicy ?? {}),
        };
    }
    getEffectiveScrubBucketMs(catalog, interactionMode) {
        const state = this.state;
        const policy = this.getScrubBucketingPolicy();
        if (!policy.enabled || interactionMode !== "scrubbing") {
            state.lastScrubBucketMs = 0;
            if (interactionMode === "idle") {
                state.lastScrubSample = null;
                state.scrubRateEWMA = 0;
            }
            return 0;
        }
        const ewma = state.scrubRateEWMA;
        if (!Number.isFinite(ewma) || ewma <= 0) {
            return 0;
        }
        let bucketMs = ewma / policy.targetResponseHz;
        bucketMs = Math.max(policy.minBucketMs, bucketMs);
        bucketMs = Math.min(policy.maxBucketMs, bucketMs);
        bucketMs = snapBucketIntervalMs(catalog, bucketMs, policy.snap);
        const last = state.lastScrubBucketMs;
        if (last > 0) {
            const ratio = Math.abs(bucketMs - last) / last;
            if (ratio < policy.hysteresisRatio) {
                bucketMs = last;
            }
        }
        state.lastScrubBucketMs = bucketMs;
        return bucketMs;
    }
    updatePrefetch(snapshot) {
        const state = this.state;
        const targetFrame = snapshot?.targetFrame ?? state.targetFrame;
        const displayFrame = snapshot?.displayFrame ?? state.displayFrame;
        const scheduledFrames = snapshot?.scheduledFrames ?? state.scheduledFrames;
        if (!targetFrame ||
            !displayFrame ||
            !this.context.device ||
            !this.props.getTileData) {
            return;
        }
        const pool = this.props.pool ?? defaultDecoderPool();
        const { coverage, bufferState } = computePrefetchBackpressureState(state.tileCache, targetFrame, displayFrame, scheduledFrames, state.visibleTileRef.tiles, this.props.bufferPolicy?.forwardFrames ?? 6);
        state.prefetcher.update({
            targetFrame,
            scheduledFrames,
            visibleTiles: state.visibleTileRef.tiles,
            device: this.context.device,
            coverage,
            bufferState,
            scoringWeights: this.props.schedulerPolicy?.scoringWeights,
            getUserTileData: this.props.getTileData,
            pool,
            playing: this.props.playing ?? false,
            playbackRate: this.props.playbackRate ?? 0,
            signal: this.props.signal,
            interactionMode: state.interactionMode,
            qualityPolicy: this.props.qualityPolicy ?? {},
            geotiffRegistry: state.geotiffRegistry,
            missingFramesWatermarkMs: this.getMissingFramesWatermarkMs(),
        });
        this.checkFrameReady(displayFrame);
    }
    /** Fire `onFrameReady` if the display frame achieves full tile coverage for the first time. */
    checkFrameReady(frame) {
        const state = this.state;
        if (state.readyFrameIds.has(frame.id)) {
            return;
        }
        if (state.tileCache.hasFullCoverage(frame.id, state.visibleTileRef.tiles, { trackAccess: false })) {
            state.readyFrameIds.add(frame.id);
            this.props.onFrameReady?.(frame);
        }
    }
    /**
     * Returns a snapshot of the current tile state for the diagnostic
     * minimap.
     *
     * @param windowSize - Optional number of frame columns to include in a
     *   playhead-centered window. Omit to capture the full timeline.
     */
    getDiagnosticSnapshot(windowSize) {
        const state = this.state;
        if (!state?.tileCache) {
            const empty = {
                frameIds: [],
                allFrameIds: [],
                playheadIndex: 0,
                zoomLevels: [],
                visibleTiles: [],
                tileGrid: {},
                tileStates: {},
                prefetchedUnusedResidentCount: 0,
                prefetchedUnusedResidentBytes: 0,
                prefetchedWastedCount: 0,
                prefetchedWastedBytes: 0,
                prefetchedUsedCount: 0,
                prefetchedLoadedCount: 0,
                abortedTasks: 0,
                scheduledFrameIds: new Set(),
                inFlightKeys: new Set(),
            };
            return empty;
        }
        return buildTileDiagSnapshot(state.tileCache, state.prefetcher, state.catalog, state.displayFrame, state.visibleTileRef?.tiles ?? [], state.scheduledFrames, windowSize);
    }
}
